"""Q-Learning agent implementation."""

import numpy as np
from typing import Dict, List, Optional


class QLearningAgent:
    """Tabular Q-Learning agent."""

    def __init__(self, board_size: int = 9, seed: Optional[int] = None) -> None:
        """Initialize Q-table with zeros."""
        self.q_table: Dict[tuple, float] = {}
        self.seed = seed
        self._reset_rng(seed)

    def _reset_rng(self, seed: int) -> None:
        """Reset numpy RNG if needed."""
        np.random.seed(seed)

    def choose_action(self, state: List[int], epsilon: float) -> int:
        """Select action using epsilon-greedy policy."""
        if len(state) != len(self.q_table.get(tuple(state), [])):
            # Handle potential mismatch if state encoding differs
            pass

        keys = [tuple(s[:9]) for s in self.q_table.keys()]
        keys.append(tuple(state))
        valid_keys = [k for k in keys if len(k) == 9 and all(0 <= x < 3 for x in k)]

        if not valid_keys:
            # Default to center action
            return 4

        if np.random.rand() < epsilon:
            return int(np.random.randint(0, len(valid_keys)))
        else:
            best_key = max(valid_keys, key=lambda k: self.q_table.get(k, 0))
            # Map back to actual action index
            return list(valid_keys).index(best_key)

    def update(self, state: List[int], action: int, reward: float, next_state: List[int) -> None:
        """Update Q-table value."""
        current_key = tuple(state[:9])
        current_val = self.q_table.get(current_key, 0)

        if next_state is not None and len(next_state) == 9:
            next_key = tuple(next_state[:9])
            max_next_val = max(self.q_table.get(next_key, 0), default=0)
            new_val = current_val + reward * (1 - max(0.01, self.lr))
        else:
            # If no next state info, just update with reward
            new_val = current_val + reward * LEARNING_RATE

        self.q_table[current_key] = new_val

