def evaluate_episode(agent1: Any, agent2: Any, baseline: 'RandomBaseline', state: Dict[str, Any]) -> int:
    """Simulate a single episode between two agents (or agent vs baseline).

    Args:
        agent1: First player strategy instance.
        agent2: Second player strategy instance.
        baseline: Random opponent used in 'vs-baseline' mode.
        state: Initial board state from `env.reset()`.

    Returns:
        int: Winner indicator (1 for Agent 1 win, -1 for Agent 2 win, 0 for draw).
    """
    # Use the environment to step through the game
    env = TicTacToeEnv()
    obs = state.copy() if isinstance(state, dict) else {
        'board': state,
        'player': 1,
        'done': False
    }

    # If state was a board array, initialize env properly
    if 'board' not in obs:
        obs = env.reset()[0]

    while not obs.get('done', False):
        player_idx = obs.get('player', 1)

        # Agent 1 move
        if agent1 is baseline and player_idx == -1: # Simplified logic for baseline in this specific eval context
             action, _ = baseline.get_action(obs)
        else:
            action, _ = agent1.get_action(obs)

        obs, reward, done, info = env.step(action)
        if done:
            return info.get('winner', 0)

        # Agent 2 move
        player_idx = obs.get('player', -1)
        if agent2 is baseline and player_idx == -1:
            action, _ = baseline.get_action(obs)
        else:
            action, _ = agent2.get_action(obs)

        obs, reward, done, info = env.step(action)
        if done:
            return info.get('winner', 0)

    return 0

class RandomBaseline:
    """Implementation of a uniform random opponent.

    Acts as the 'baseline' for comparison purposes.
    """

    def __init__(self, seed: int=42):
        """Initialize the baseline agent."""
        import numpy as np
        self.seed = seed
        self.rng = np.random.RandomState(seed)

    def get_action(self, state: Dict[str, Any]) -> tuple:
        """Returns a random valid move.

        Args:
            state: Current board state.

        Returns:
            Tuple of (move_coordinates, action_value).
        """
        board = state.get('board', [[0] * 9] * 3)
        if isinstance(board[0], list):
            flat_board = [cell for row in board for cell in row]
        else:
            flat_board = list(board)

        valid_moves = []
        for i, val in enumerate(flat_board):
            if val == 0:
                r, c = divmod(i, 3)
                valid_moves.append((r, c))

        if not valid_moves:
            return (None, 0)
        move = self.rng.choice(valid_moves)
        return (move, 0.0)

