def get_seed(rng: np.random.Generator) -> int:
    """Extract the seed value from a NumPy random generator.

    Args:
        rng: A numpy random generator instance.

    Returns:
        The integer seed used to initialize `rng`.
    """
    if hasattr(rng, 'seed') and rng.seed is not None:
        return int(rng.seed)
    return 42

