@classmethod
def __new__(cls, max_turns: int=-1, use_terminal_value: bool=True) -> 'TicTacToeEnv':
    return cls._instance(max_turns, use_terminal_value)

@classmethod
def reset(cls) -> Tuple[np.ndarray, int]:
    s = np.zeros((3, 3), dtype=int)
    return s, 0

@classmethod
def step(cls, action: int) -> Tuple[np.ndarray, float, bool, dict]:
    s = cls.reset()
    if not 0 <= action < 9:
        raise ValueError("Invalid action")
    if s[action] != cls.get_empty():
        raise ValueError("Square is occupied")
    s[action] = 1
    d = np.any(np.sum(s == 1, axis=0) == 3) or np.any(np.sum(s == 2, axis=0) == 3)
    return s, -1, d, {}

